-- V1.3.1 abuse bounds (docs/v131/lot1-securite.md, D8 and D11). Applies after 20261114180000. Additive: no function body is
-- replaced, no grant is widened, no existing row is changed or deleted by this file.
--   1. D11. public.titan_submit_cache_reconciliation (called at web start-up, js/state.js) inserted one report per call without
--      any bound: 737 rows for 25 accounts in production, 300 rows from 300 consecutive calls on the bench. A BEFORE INSERT
--      trigger now keeps at most 20 reports per account over 24 hours and silently skips the rest. The RPC itself is unchanged:
--      it still answers with the same comparison, with "reportId": null when the report was not kept, which the client ignores.
--   2. D11. Those reports are diagnostics: they are now kept 90 days (rule cache_reconciliation, run by
--      private.titan_purge_expired_data_v1), instead of indefinitely. Published in docs/DATA_RETENTION.md and legal_privacy.html.
--   3. D8. The public "avatars" bucket accepted any file of any size from any signed-in account, and no client uploads to it any
--      more. Its objects are now limited to 2 MB and to PNG, JPEG or WebP images. Removing the two INSERT policies needs the
--      owner of storage.objects (supabase_storage_admin): Storage settings of the dashboard, not SQL.
-- The caller owns the transaction: never BEGIN/COMMIT here.
-- Rollback: (1) drop trigger titan_cache_reconciliation_daily_cap on public.titan_cache_reconciliation_reports;
-- (2) delete from private.titan_retention_rules where id = 'cache_reconciliation';
-- (3) update storage.buckets set file_size_limit = null, allowed_mime_types = null where id = 'avatars'.

-- 1. At most 20 reports per account and rolling day.
create or replace function private.titan_cache_reconciliation_daily_cap()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
begin
  -- One account's concurrent start-ups are serialized on this key, so the cap holds under overlapping calls.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('titan_cache_reconciliation:' || new.user_id::text, 0));
  if (select count(*) from public.titan_cache_reconciliation_reports r
      where r.user_id = new.user_id and r.created_at > pg_catalog.now() - interval '24 hours') >= 20 then
    return null;
  end if;
  return new;
end;
$function$;
revoke all on function private.titan_cache_reconciliation_daily_cap() from public, anon, authenticated, service_role;

drop trigger if exists titan_cache_reconciliation_daily_cap on public.titan_cache_reconciliation_reports;
create trigger titan_cache_reconciliation_daily_cap before insert on public.titan_cache_reconciliation_reports
  for each row execute function private.titan_cache_reconciliation_daily_cap();

create index if not exists titan_cache_reconciliation_reports_user_created_idx
  on public.titan_cache_reconciliation_reports (user_id, created_at desc);

-- 2. Diagnostics expire after 90 days.
insert into private.titan_retention_rules (id, relation, time_column, keep, extra_where, purpose) values
  ('cache_reconciliation', 'public.titan_cache_reconciliation_reports', 'created_at', interval '90 days', null,
   'rapports techniques de cohérence entre l''appareil et le compte')
on conflict (id) do update
  set relation = excluded.relation, time_column = excluded.time_column, keep = excluded.keep,
      extra_where = excluded.extra_where, purpose = excluded.purpose;

-- 3. The avatars bucket only takes small images. Skipped on a database without Supabase Storage.
do $migration$
begin
  if to_regclass('storage.buckets') is not null then
    update storage.buckets
       set file_size_limit = 2097152,
           allowed_mime_types = array['image/png', 'image/jpeg', 'image/webp']
     where id = 'avatars';
  end if;
end
$migration$;
